delete_user.beforeRequest:
const answer = call({ method: 'POST', url: '/PasswordVault/API/auth/Cyberark/Logon/', headers: { 'Content-Type': 'application/json' } });
const token = typeof answer === 'string' ? answer.replace(/^["']|["']$/g, '').trim() : '';
if (!token) throw new Error('Invalid token received from authentication');
if (String(inputs.confirmDeletion) !== 'true') throw new Error('Please check the confirmation box to proceed with user deletion.');
request.headers.Authorization = token;
return request;

